let worlds=[],page=0,total=0,pages=1,requestId=0;const el=id=>document.getElementById(id);function render(){const list=worlds;el('worlds').replaceChildren();for(const t of list){const a=document.createElement('article'),img=document.createElement('img'),h=document.createElement('h2'),small=document.createElement('small'),p=document.createElement('p'),dl=document.createElement('dl');img.src='/assets/planets/'+t.id+'.svg';img.alt=t.name;img.loading='lazy';h.textContent=t.name;small.textContent=t.rarity+' · '+(t.familyLabel||t.family)+' · '+(t.uniquePerRound?'Once per round':'Environment type');p.textContent=t.lore;for(const [k,v] of [['Habitability',t.habitability+'%'],['Biodiversity',t.biodiversity+'%'],['Moisture',t.moisture+'%'],['Rockiness',t.rockiness+'%'],['Founding population',t.basePopulation],['Growth',t.growthPercent+'%'],['Travel ETA',(t.travelEtaBonus||0)+' tick'],['Bonus salvage',(t.salvageBonusPercent||0)+'%'],['Ship price reduction',(t.shipCostDiscountPercent||0)+'%']]){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=k;dd.textContent=v;dl.append(dt,dd);}a.append(img,small,h,dl,p);el('worlds').append(a);}el('count').textContent=total+' worlds · page '+(page+1)+' / '+pages;el('prev').disabled=page===0;el('next').disabled=page+1>=pages;}async function load(){const id=++requestId;el('count').textContent='Loading planetary surveys…';try{const r=await fetch('/api/planet-catalog?'+new URLSearchParams({q:el('search').value,family:el('family').value,page}));if(!r.ok)throw Error('Catalogue unavailable.');const data=await r.json();if(id!==requestId)return;worlds=data.worlds;page=data.page;total=data.total;pages=data.pages;render();}catch(error){if(id===requestId)el('count').textContent=error.message;}}let timer;for(const id of ['search','family'])el(id).oninput=()=>{page=0;clearTimeout(timer);timer=setTimeout(load,id==='search'?200:0);};el('prev').onclick=()=>{page--;load();};el('next').onclick=()=>{page++;load();};load();
